// Standalone fallback: resolve the pricing-relevant client_config from Notion by client_id.
// The n8n Notion node flattens properties as 'property_<snake_cased_name>'; prop() tolerates both.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
// Notion hands each property over in whatever shape n8n's node uses for that property type. The
// previous prop() ended in `?? p ?? null`, so an unrecognised shape leaked out as the RAW OBJECT
// and every downstream string comparison failed SILENTLY. Two of those failures were live: a
// Select ({name:'proposal_only'}) never matched a tier, and an EMPTY rich_text arrived as [] or
// {} — both truthy — so "no pricing_sheet_id" read as "pricing configured". Together they routed
// a proposal_only client into Module 3. Normalise to a string or null; booleans pass through.
function asText(v){ if(v==null) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='number'||typeof v==='boolean') return String(v); if(Array.isArray(v)) return v.map(asText).filter(Boolean).join(' ').trim(); if(typeof v==='object') return asText(v.name ?? v.value ?? v.plain_text ?? v.content ?? (v.select&&v.select.name) ?? (v.status&&v.status.name) ?? v.text ?? ''); return ''; }
function prop(props, name){ const keys=[name,'property_'+name,'property_'+String(name).toLowerCase().replace(/ /g,'_')]; let p; for(const k of keys){ const v=props&&props[k]; if(v!==undefined&&v!==null){ p=v; break; } } if(typeof p==='boolean') return p; const t=asText(p); return t===''?null:t; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);
const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  pricing_sheet_id: prop(match,'pricing_sheet_id'),
  commercial_contact_email: prop(match,'commercial_contact_email'),
  notification_chat_id: prop(match,'notification_chat_id')
};
return [{ json: { client_id: wantId, client_config, data: trigger.data, status: 'ok', errors: [] } }];

// Single merge point for both branches (config passed in vs looked up standalone).
// Emits a uniform { client_id, client_config, data } that downstream nodes reference by name.
const j = $json;
const client_config = j.client_config || {};
if (!client_config.pricing_sheet_id && !client_config.rate_card) {
  throw new Error(`No pricing source for client '${j.client_id}': set 'pricing_sheet_id' in the Notion registry (the client's pricing Google Sheet) or pass client_config.rate_card. See docs/PRICING-SHEET-TEMPLATE.md.`);
}
return [{ json: { client_id: j.client_id, client_config, data: j.data || {} } }];

// Assemble the rate_card object from the client's pricing sheet rows.
// Expected sheet columns (tab named 'Pricing'): type | key | value  (docs/PRICING-SHEET-TEMPLATE.md).
//   type='rate'  -> key is a labour category, value is its hourly rate.
//   type='param' -> key is one of margin_pct, risk_pct, discount_pct, payment_terms, currency.
// An inline client_config.rate_card (if provided) overrides the sheet entirely.
const env = $('Resolve Config').first().json;
const cfg = env.client_config || {};

let rate_card;
if (cfg.rate_card) {
  rate_card = cfg.rate_card;
} else {
  const rows = $('Read Pricing Sheet').all().map(i => i.json);
  const rate_by_category = {};
  let margin_pct = 0, risk_pct = 0, discount_pct = 0, payment_terms = '', currency = null;
  for (const r of rows) {
    const type = String(r.type ?? '').trim().toLowerCase();
    const key = String(r.key ?? '').trim();
    const val = r.value;
    if (!key) continue;
    if (type === 'rate') { rate_by_category[key] = Number(val); }
    else if (type === 'param') {
      if (key === 'margin_pct') margin_pct = Number(val);
      else if (key === 'risk_pct') risk_pct = Number(val);
      else if (key === 'discount_pct') discount_pct = Number(val);
      else if (key === 'payment_terms') payment_terms = String(val);
      else if (key === 'currency') currency = String(val);
    }
  }
  if (Object.keys(rate_by_category).length === 0) {
    throw new Error(`Pricing sheet for '${env.client_id}' produced no rate rows. Check the 'Pricing' tab has columns type|key|value and at least one type='rate' row. See docs/PRICING-SHEET-TEMPLATE.md.`);
  }
  rate_card = { rate_by_category, margin_pct, risk_pct, discount_pct, payment_terms, currency };
}
return [{ json: { client_id: env.client_id, client_config: cfg, data: env.data, rate_card } }];

// Cifral pricing logic — SOURCE OF TRUTH mirrored in modules/pricing/pricing_core.js.
// Plain JavaScript (self-hosted n8n has no Python). If the formula changes, change both.
// Pricing DATA (rates/margins) comes from the client's Google Sheet, not from here.
// === PRICING CORE START ===
function isNumber(value) { return typeof value === 'number' && Number.isFinite(value); }
function roundMoney(value) { return Math.round((value + Number.EPSILON) * 100) / 100; }

function computePricing({ materialsCost, hoursByCategory, rateByCategory, marginPct, riskPct, discountPct, paymentTerms, currency = null }) {
  hoursByCategory = hoursByCategory ?? {};
  rateByCategory = rateByCategory ?? {};
  if (!isNumber(materialsCost) || materialsCost < 0) throw new Error('materials_cost must be a number >= 0');
  if (!isNumber(marginPct) || marginPct < 0) throw new Error('margin_pct must be a number >= 0');
  if (!isNumber(riskPct) || riskPct < 0) throw new Error('risk_pct must be a number >= 0');
  if (!isNumber(discountPct) || discountPct < 0 || discountPct > 1) throw new Error('discount_pct must be a number between 0 and 1');
  let labor = 0;
  for (const [category, hours] of Object.entries(hoursByCategory)) {
    if (!isNumber(hours) || hours < 0) throw new Error(`hours for '${category}' must be a number >= 0`);
    if (!Object.prototype.hasOwnProperty.call(rateByCategory, category)) throw new Error(`no rate configured for category '${category}'`);
    const rate = rateByCategory[category];
    if (!isNumber(rate) || rate < 0) throw new Error(`rate for '${category}' must be a number >= 0`);
    labor += hours * rate;
  }
  const subtotal = materialsCost + labor;
  const multiplier = (1 + riskPct) * (1 + marginPct) * (1 - discountPct);
  const total = subtotal * multiplier;

  // Per-line breakdown, so the proposal can show a price table instead of a bare total. Each line
  // carries the internal cost basis (amount) AND the customer-facing price (sell_amount = amount
  // scaled by the same multiplier as the total). A quotation shows sell prices only — margin and
  // risk are baked in, never itemised for the customer.
  const lines = [];
  if (materialsCost > 0) lines.push({ category: 'materials', hours: null, rate: null, amount: roundMoney(materialsCost) });
  for (const [category, hours] of Object.entries(hoursByCategory)) {
    lines.push({ category, hours, rate: rateByCategory[category], amount: roundMoney(hours * rateByCategory[category]) });
  }
  for (const line of lines) line.sell_amount = roundMoney(line.amount * multiplier);
  // Absorb per-line rounding into the largest line: a price table that doesn't add up is worse
  // than no table.
  const roundedTotal = roundMoney(total);
  const residual = roundMoney(roundedTotal - lines.reduce((sum, l) => sum + l.sell_amount, 0));
  if (residual !== 0 && lines.length > 0) {
    const largest = lines.reduce((a, b) => (b.sell_amount > a.sell_amount ? b : a));
    largest.sell_amount = roundMoney(largest.sell_amount + residual);
  }

  const result = { subtotal: roundMoney(subtotal), margin_pct: marginPct, risk_pct: riskPct, discount_pct: discountPct, total: roundedTotal, payment_terms: paymentTerms, lines };
  if (currency) result.currency = currency;
  return result;
}
// === PRICING CORE END ===

// --- n8n wrapper ---
const output = [];
for (const item of $input.all()) {
  const src = item.json ?? {};
  const data = src.data ?? {};
  const rateCard = src.rate_card ?? {};
  const hours = data.hours_by_category ?? {};
  const result = computePricing({
    materialsCost: data.materials_cost ?? 0,
    hoursByCategory: hours,
    rateByCategory: rateCard.rate_by_category ?? {},
    marginPct: rateCard.margin_pct ?? 0,
    riskPct: rateCard.risk_pct ?? 0,
    discountPct: rateCard.discount_pct ?? 0,
    paymentTerms: rateCard.payment_terms ?? '',
    currency: rateCard.currency ?? null,
  });
  result.priced_categories = Object.keys(hours);
  output.push({ json: { client_id: src.client_id ?? null, client_config: src.client_config ?? null, status: 'ok', errors: [], data: result } });
}
return output;
